mapper.select:
select s.*, st.name as studentName, st.student_no as studentNo, c.name as className, sub.name as subjectName, e.exam_date as examDate, e.exam_time as examTime from score s left join student st on s.student_id = st.id left join class c on st.class_id = c.id left join exam e on s.exam_id = e.id left join subject sub on e.subject_id = sub.id where 1=1
and st.class_id = #{dto.classId}
and e.subject_id = #{dto.subjectId}
and s.student_id = #{dto.studentId}
order by s.id desc

SELECT c.name AS className, su.name AS subjectName, sem.name AS semesterName, e.exam_date AS examDate, COUNT(*) AS studentCount, ROUND(AVG(s.score), 2) AS avgScore, MAX(s.score) AS maxScore, MIN(s.score) AS minScore FROM score s JOIN exam e ON s.exam_id = e.id JOIN class c ON e.class_id = c.id JOIN subject su ON e.subject_id = su.id JOIN semester sem ON e.semester_id = sem.id
AND c.id = #{dto.classId} AND su.id = #{dto.subjectId} AND sem.id = #{dto.semesterId}
GROUP BY e.id, c.name, su.name, sem.name, e.exam_date ORDER BY e.exam_date, c.id, su.id
